#!/usr/bin/env python3
"""Render the fixed original package into an offline preview. No URL/media input."""
import json,pathlib
root=pathlib.Path(__file__).resolve().parent.parent
pkg=(root/'midnight-beacon.music-release.json').read_text()
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; media-src data: blob:; script-src 'unsafe-inline'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><link rel="icon" href="data:,"><title>Midnight Beacon · BEACN Labs</title><style>
*{box-sizing:border-box}body{margin:0;background:#091219;color:#edf4ef;font:16px/1.5 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:48px 32px 32px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #29414b;padding-bottom:24px;margin-bottom:48px}.brand{font-weight:800;letter-spacing:3px}.tag{font-size:12px;letter-spacing:2px;color:#9db3ba}.release{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}#cover{display:block;width:100%;aspect-ratio:1;border:1px solid #34525c}.eyebrow{color:#edc85b;font-size:12px;font-weight:700;letter-spacing:2px}h1{font-size:56px;line-height:1.04;letter-spacing:-2px;margin:16px 0 20px}p{color:#a8bdc5;margin:0 0 24px;max-width:42ch}.spec{display:flex;gap:20px;color:#65ede3;font:13px/1.5 monospace;margin:24px 0}button,a.download{display:block;width:100%;padding:16px 24px;border:0;border-radius:4px;background:#edc85b;color:#101b21;font:700 16px system-ui;cursor:pointer;text-align:center;text-decoration:none}button:hover{background:#f5d67d}button:focus-visible,a:focus-visible{outline:3px solid #65ede3;outline-offset:4px}button:disabled{opacity:.5;cursor:wait}.track{margin:16px 0 0;width:100%;accent-color:#65ede3}#state{font:12px/1.5 monospace;color:#a8bdc5;min-height:36px;margin-top:12px}.package{margin-top:48px;border-top:1px solid #29414b;padding-top:24px;display:grid;grid-template-columns:1fr 1fr;gap:56px}.package h2{font-size:16px;margin:0 0 8px}.package p{font-size:14px;margin-bottom:16px}.package code{display:block;font:11px/1.6 monospace;color:#65ede3;overflow-wrap:anywhere}a.download{background:transparent;color:#edf4ef;border:1px solid #51636a;font-size:14px;padding:12px 24px;max-width:320px}.foot{margin-top:24px;color:#889fa8;font-size:12px} @media(max-width:700px){main{padding:24px}header{margin-bottom:28px;padding-bottom:20px}.brand{font-size:14px}.tag{font-size:10px;letter-spacing:1px}.release,.package{grid-template-columns:1fr;gap:28px}h1{font-size:44px;letter-spacing:-1.5px}.spec{gap:16px}.package{margin-top:28px;padding-top:24px}.foot{margin-top:20px}}
</style><main><header><span class="brand">BEACN LABS</span><span class="tag">ORIGINAL DEMO / 001</span></header><section class="release"><img id="cover" alt="Midnight Beacon cover: a cyan beacon inside concentric signal rings, with an amber light"><div><div class="eyebrow">A SMALL SIGNAL FROM THE NIGHT</div><h1>Midnight<br>Beacon</h1><p>A four-bar chiptune: warm triangle bass, a rising pulse melody and a little light at the end.</p><div class="spec"><span>08 SECONDS</span><span>120 BPM</span><span>8,600 BYTES</span></div><button id="play">Play the signal</button><audio id="audio" class="track" controls preload="metadata"></audio><div id="state" role="status">Playback starts only when you press play.</div></div></section><section class="package"><div><h2>One exact music package</h2><p>Original compressed audio, SVG cover and declared credits. Synthetic transaction estimate: 13,697 of 16,384 bytes.</p><a class="download" id="download" download="midnight-beacon.music-release.json">Download Music package</a></div><div><h2>BEACN Labs · AI-assisted demo</h2><p>Composition, synthesis and cover produced with Codex. Credit declarations do not certify authorship or rights.</p><code id="hash"></code></div></section><div class="foot">Local showcase · no mint, wallet connection, signature or submission.</div></main><script>
const packetText=PACKET_JSON_STRING; const pkg=JSON.parse(packetText);const audio=document.getElementById('audio'),play=document.getElementById('play'),state=document.getElementById('state');
document.getElementById('cover').src=pkg.bundle.files[0].uri;audio.src=pkg.bundle.files[1].uri;document.getElementById('hash').textContent='PACKAGE SHA-256 / '+pkg.packageHash;
document.getElementById('download').href=URL.createObjectURL(new Blob([packetText],{type:'application/json'}));
window.preview={playClicks:0,started:false,ended:false,decoder:null};
play.addEventListener('click',async()=>{try{if(!audio.paused){audio.pause();return}if(audio.ended)audio.currentTime=0;window.preview.playClicks++;await audio.play();if(!window.preview.decoder){const bytes=Uint8Array.from(atob(pkg.bundle.files[1].uri.split(',')[1]),c=>c.charCodeAt(0));const ctx=new AudioContext();const buffer=await ctx.decodeAudioData(bytes.buffer);let peak=0,sum=0,clipped=0;for(let ch=0;ch<buffer.numberOfChannels;ch++){for(const x of buffer.getChannelData(ch)){peak=Math.max(peak,Math.abs(x));sum+=x*x;if(Math.abs(x)>=1)clipped++;}}window.preview.decoder={duration:buffer.duration,sampleRate:buffer.sampleRate,channels:buffer.numberOfChannels,frames:buffer.length,peak,rms:Math.sqrt(sum/(buffer.length*buffer.numberOfChannels)),clipped};await ctx.close();}}catch(e){state.textContent='Playback failed: '+e.message;window.preview.error=e.message;}});
audio.addEventListener('playing',()=>{window.preview.started=true;play.textContent='Pause the signal';state.textContent='Playing exact embedded Opus bytes.'});audio.addEventListener('pause',()=>{play.textContent=audio.ended?'Replay the signal':'Play the signal'});audio.addEventListener('ended',()=>{window.preview.ended=true;state.textContent='Eight seconds. Audio and cover stay in the package.'});
</script></html>'''
(root/'index.html').write_text(html.replace('PACKET_JSON_STRING',json.dumps(pkg)))
